     3	import java.sql.Connection;
     4	import java.sql.DriverManager;
     5	import java.sql.SQLException;
     6	import java.sql.Statement;
     7	
     8	public class DatabaseSetup {
     9	    private final String dbUrl;
    10	    private final String dbUser;
    11	    private final String dbPassword;
    12	
    13	    public DatabaseSetup(String dbUrl, String dbUser, String dbPassword) {
    14	        this.dbUrl = dbUrl;
    15	        this.dbUser = dbUser;
    16	        this.dbPassword = dbPassword;
    17	    }
    18	
    19	    public void initialize() {
    20	        try (Connection conn = DriverManager.getConnection(dbUrl, dbUser, dbPassword);
    21	             Statement stmt = conn.createStatement()) {
    22	
    23	            stmt.execute("""
    24	                CREATE TABLE IF NOT EXISTS rooms (
    25	                    number VARCHAR(10) PRIMARY KEY,
    26	                    type VARCHAR(20) NOT NULL
    27	                )
    28	                """);
    29	
    30	            stmt.execute("""
    31	                CREATE TABLE IF NOT EXISTS reservations (
    32	                    id BIGSERIAL PRIMARY KEY,
    33	                    room_number VARCHAR(10) NOT NULL,
    34	                    room_type VARCHAR(20) NOT NULL,
    35	                    guest_name VARCHAR(255) NOT NULL,
    36	                    guest_email VARCHAR(255) NOT NULL,
    37	                    guest_cpf VARCHAR(14) NOT NULL,
    38	                    check_in DATE NOT NULL,
    39	                    check_out DATE NOT NULL,
    40	                    guests INTEGER NOT NULL,
    41	                    rate_plan VARCHAR(20) NOT NULL,
    42	                    status VARCHAR(20) NOT NULL,
    43	                    amount_paid DECIMAL(10, 2) NOT NULL DEFAULT 0,
    44	                    refund DECIMAL(10, 2)
    45	                )
    46	                """);
    47	
    48	            stmt.execute("""
    49	                CREATE TABLE IF NOT EXISTS messages (
    50	                    id BIGSERIAL PRIMARY KEY,
    51	                    channel VARCHAR(20) NOT NULL,
    52	                    recipient VARCHAR(255) NOT NULL,
    53	                    subject VARCHAR(500) NOT NULL,
    54	                    body TEXT NOT NULL
    55	                )
    56	                """);
    57	
    58	            long roomCount = 0;
    59	            var rs = stmt.executeQuery("SELECT COUNT(*) FROM rooms");
    60	            if (rs.next()) {
    61	                roomCount = rs.getLong(1);
    62	            }
    63	
    64	            if (roomCount == 0) {
    65	                stmt.execute("INSERT INTO rooms (number, type) VALUES ('101', 'STANDARD')");
    66	                stmt.execute("INSERT INTO rooms (number, type) VALUES ('102', 'STANDARD')");
    67	                stmt.execute("INSERT INTO rooms (number, type) VALUES ('201', 'DELUXE')");
    68	                stmt.execute("INSERT INTO rooms (number, type) VALUES ('202', 'DELUXE')");
    69	                stmt.execute("INSERT INTO rooms (number, type) VALUES ('301', 'SUITE')");
    70	            }
    71	
    72	        } catch (SQLException e) {
    73	            throw new RuntimeException("Error initializing database", e);
    74	        }
    75	    }
    76	}
