    16	        this.reportService = reportService;
    17	    }
    18	
    19	    public void getOccupancyReport(Context ctx) {
    20	        try {
    21	            String dateParam = ctx.queryParam("date");
    22	            if (dateParam == null) {
    23	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Date parameter is required"));
    24	                return;
    25	            }
    26	
    27	            LocalDate date = LocalDate.parse(dateParam, DateTimeFormatter.ISO_LOCAL_DATE);
    28	            String csv = reportService.generateOccupancyReport(date);
    29	
    30	            ctx.contentType("text/csv; charset=utf-8");
    31	            ctx.result(csv);
    32	        } catch (DateTimeParseException e) {
    33	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid date format"));
    34	        }
    35	    }
    36	
    37	    public void getRevenueReport(Context ctx) {
    38	        try {
    39	            String monthParam = ctx.queryParam("month");
    40	            if (monthParam == null) {
    41	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Month parameter is required"));
    42	                return;
    43	            }
    44	
