     1	package br.com.pousadamarealta.api;
     2	
     3	import br.com.pousadamarealta.api.dto.*;
     4	import br.com.pousadamarealta.domain.RatePlan;
     5	import br.com.pousadamarealta.domain.Reservation;
     6	import br.com.pousadamarealta.domain.ReservationStatus;
     7	import br.com.pousadamarealta.service.ReservationService;
     8	import br.com.pousadamarealta.service.RoomService;
     9	import io.javalin.http.Context;
    10	
    11	public class ReservationController {
    12	    private final ReservationService reservationService;
    13	    private final RoomService roomService;
    14	
    15	    public ReservationController(ReservationService reservationService, RoomService roomService) {
    16	        this.reservationService = reservationService;
    17	        this.roomService = roomService;
    18	    }
    19	
    20	    public void createReservation(Context ctx) {
    21	        try {
    22	            CreateReservationRequest request = ctx.bodyAsClass(CreateReservationRequest.class);
    23	
    24	            if (request.checkIn() == null || request.checkOut() == null) {
    25	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Check-in and check-out dates are required"));
    26	                return;
    27	            }
    28	
    29	            if (!request.checkOut().isAfter(request.checkIn())) {
    30	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Check-out must be after check-in"));
    31	                return;
    32	            }
    33	
    34	            if (request.guests() < 1) {
    35	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "At least one guest is required"));
    36	                return;
    37	            }
    38	
    39	            var room = roomService.getRoomByNumber(request.roomNumber())
    40	                .orElseThrow(() -> new RoomNotFoundException("Room not found"));
    41	
    42	            RatePlan ratePlan;
    43	            try {
    44	                ratePlan = RatePlan.valueOf(request.ratePlan());
    45	            } catch (IllegalArgumentException e) {
    46	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid rate plan"));
    47	                return;
    48	            }
    49	
    50	            Reservation reservation = reservationService.createReservation(
    51	                request.roomNumber(),
    52	                room.getType(),
    53	                request.guestName(),
    54	                request.guestEmail(),
    55	                request.guestCpf(),
    56	                request.checkIn(),
    57	                request.checkOut(),
    58	                request.guests(),
    59	                ratePlan
    60	            );
    61	
    62	            ctx.status(201).json(ReservationDTO.from(reservation));
    63	
    64	        } catch (RoomNotFoundException e) {
    65	            ctx.status(404).json(new ErrorResponse("ROOM_NOT_FOUND", e.getMessage()));
    66	        } catch (ReservationService.RoomUnavailableException e) {
    67	            ctx.status(409).json(new ErrorResponse("ROOM_UNAVAILABLE", e.getMessage()));
    68	        } catch (ReservationService.CapacityExceededException e) {
    69	            ctx.status(422).json(new ErrorResponse("CAPACITY_EXCEEDED", e.getMessage()));
    70	        } catch (Exception e) {
    71	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid request data"));
    72	        }
    73	    }
    74	
    75	    public void getReservation(Context ctx) {
    76	        try {
    77	            long id = Long.parseLong(ctx.pathParam("id"));
    78	            Reservation reservation = reservationService.getReservation(id)
    79	                .orElseThrow(() -> new ReservationService.ReservationNotFoundException("Reservation not found"));
    80	            ctx.json(ReservationDTO.from(reservation));
    81	        } catch (ReservationService.ReservationNotFoundException e) {
    82	            ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", e.getMessage()));
    83	        } catch (NumberFormatException e) {
    84	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid reservation ID"));
    85	        }
    86	    }
    87	
    88	    public void confirmReservation(Context ctx) {
    89	        try {
    90	            long id = Long.parseLong(ctx.pathParam("id"));
    91	            Reservation reservation = reservationService.confirmReservation(id);
    92	            ctx.json(ReservationDTO.from(reservation));
    93	        } catch (ReservationService.ReservationNotFoundException e) {
    94	            ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", e.getMessage()));
    95	        } catch (ReservationService.OperationNotAllowedException e) {
    96	            ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED", e.getMessage()));
    97	        } catch (NumberFormatException e) {
    98	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid reservation ID"));
    99	        }
   100	    }
   101	
   102	    public void cancelReservation(Context ctx) {
   103	        try {
   104	            long id = Long.parseLong(ctx.pathParam("id"));
   105	            Reservation reservation = reservationService.cancelReservation(id);
   106	            ctx.json(ReservationDTO.from(reservation));
   107	        } catch (ReservationService.ReservationNotFoundException e) {
   108	            ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", e.getMessage()));
   109	        } catch (ReservationService.OperationNotAllowedException e) {
   110	            ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED", e.getMessage()));
   111	        } catch (NumberFormatException e) {
   112	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid reservation ID"));
   113	        }
   114	    }
   115	
   116	    public void checkIn(Context ctx) {
   117	        try {
   118	            long id = Long.parseLong(ctx.pathParam("id"));
   119	            Reservation reservation = reservationService.checkIn(id);
   120	            ctx.json(ReservationDTO.from(reservation));
   121	        } catch (ReservationService.ReservationNotFoundException e) {
   122	            ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", e.getMessage()));
   123	        } catch (ReservationService.OperationNotAllowedException e) {
   124	            ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED", e.getMessage()));
   125	        } catch (NumberFormatException e) {
   126	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid reservation ID"));
   127	        }
   128	    }
   129	
   130	    public void checkOut(Context ctx) {
   131	        try {
   132	            long id = Long.parseLong(ctx.pathParam("id"));
   133	            Reservation reservation = reservationService.checkOut(id);
   134	            ctx.json(DocumentDTO.from(reservation));
   135	        } catch (ReservationService.ReservationNotFoundException e) {
   136	            ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", e.getMessage()));
   137	        } catch (ReservationService.OperationNotAllowedException e) {
   138	            ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED", e.getMessage()));
   139	        } catch (NumberFormatException e) {
   140	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid reservation ID"));
   141	        }
   142	    }
   143	
   144	    public void getDocument(Context ctx) {
   145	        try {
   146	            long id = Long.parseLong(ctx.pathParam("id"));
   147	            Reservation reservation = reservationService.getReservation(id)
   148	                .orElseThrow(() -> new ReservationService.ReservationNotFoundException("Reservation not found"));
   149	
   150	            if (reservation.getStatus() != ReservationStatus.CONFIRMED &&
   151	                reservation.getStatus() != ReservationStatus.CHECKED_IN &&
   152	                reservation.getStatus() != ReservationStatus.CHECKED_OUT) {
   153	                ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED",
   154	                    "Document only available for confirmed reservations"));
   155	                return;
   156	            }
   157	
   158	            ctx.json(DocumentDTO.from(reservation));
   159	        } catch (ReservationService.ReservationNotFoundException e) {
   160	            ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", e.getMessage()));
   161	        } catch (NumberFormatException e) {
   162	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid reservation ID"));
   163	        }
   164	    }
   165	
   166	    private static class RoomNotFoundException extends RuntimeException {
   167	        public RoomNotFoundException(String message) {
   168	            super(message);
   169	        }
   170	    }
   171	}
