    50	        BigDecimal total = BigDecimal.ZERO;
    51	
    52	        for (Reservation r : reservations) {
    53	            BigDecimal revenue = r.getAmountPaid().subtract(r.getRefund() != null ? r.getRefund() : BigDecimal.ZERO);
