    56	                    r.getId(),
    57	                    r.getRoomNumber(),
    58	                    r.getCheckIn().format(DATE_FORMATTER),
    59	                    r.getCheckOut().format(DATE_FORMATTER),
    60	                    r.getStatus(),
    61	                    revenue));
    62	                total = total.add(revenue);
    63	            }
    64	        }
    65	
