     8	public class ReservationService {
     9	    private final ReservationRepository reservationRepository;
    10	    private final NotificationService notificationService;
    11	
    12	    public ReservationService(ReservationRepository reservationRepository, NotificationService notificationService) {
    13	        this.reservationRepository = reservationRepository;
