    16	
    17	    public Reservation createReservation(String roomNumber, RoomType roomType, String guestName,
    18	                                        String guestEmail, String guestCpf, java.time.LocalDate checkIn,
    19	                                        java.time.LocalDate checkOut, int guests, RatePlan ratePlan) {
    20	
    21	        if (reservationRepository.hasConflict(roomNumber, checkIn, checkOut, null)) {
    22	            throw new RoomUnavailableException("Room is not available for the selected dates");
    23	        }
    24	
    25	        if (guests > roomType.getCapacity()) {
    26	            throw new CapacityExceededException("Number of guests exceeds room capacity");
    27	        }
    28	
    29	        if (guests < 1) {
    30	            throw new IllegalArgumentException("At least one guest is required");
    31	        }
    32	
    33	        Reservation reservation = new Reservation(roomNumber, roomType, guestName, guestEmail,
    34	                                                  guestCpf, checkIn, checkOut, guests, ratePlan);
    35	        return reservationRepository.save(reservation);
    36	    }
    37	
    38	    public Optional<Reservation> getReservation(Long id) {
    39	        return reservationRepository.findById(id);
    40	    }
    41	
    42	    public Reservation confirmReservation(Long id) {
    43	        Reservation reservation = reservationRepository.findById(id)
    44	            .orElseThrow(() -> new ReservationNotFoundException("Reservation not found"));
    45	
    46	        if (reservation.getStatus() != ReservationStatus.PENDING) {
    47	            throw new OperationNotAllowedException("Only pending reservations can be confirmed");
    48	        }
    49	
    50	        reservation.confirm();
    51	        reservationRepository.save(reservation);
    52	
    53	        notificationService.notifyConfirmation(reservation);
    54	
    55	        return reservation;
    56	    }
    57	
