    59	        Reservation reservation = reservationRepository.findById(id)
    60	            .orElseThrow(() -> new ReservationNotFoundException("Reservation not found"));
    61	
    62	        if (reservation.getStatus() != ReservationStatus.PENDING &&
    63	            reservation.getStatus() != ReservationStatus.CONFIRMED) {
    64	            throw new OperationNotAllowedException("Only pending or confirmed reservations can be cancelled");
    65	        }
    66	
    67	        boolean wasConfirmed = reservation.getStatus() == ReservationStatus.CONFIRMED;
    68	        reservation.cancel();
    69	        reservationRepository.save(reservation);
    70	
    71	        notificationService.notifyCancellation(reservation, wasConfirmed);
    72	
    73	        return reservation;
    74	    }
