    24	    private BigDecimal amountPaid;
    25	    private BigDecimal refund;
    26	
    27	    public Reservation(String roomNumber, RoomType roomType, String guestName, String guestEmail,
    28	                      String guestCpf, LocalDate checkIn, LocalDate checkOut, int guests, RatePlan ratePlan) {
    29	        this.roomNumber = roomNumber;
    30	        this.roomType = roomType;
    31	        this.guestName = guestName;
    32	        this.guestEmail = guestEmail;
    33	        this.guestCpf = guestCpf;
    34	        this.checkIn = checkIn;
    35	        this.checkOut = checkOut;
    36	        this.guests = guests;
    37	        this.ratePlan = ratePlan;
    38	        this.nights = (int) checkIn.datesUntil(checkOut).count();
    39	        this.subtotal = calculateSubtotal();
    40	        this.discount = calculateDiscount();
    41	        this.total = subtotal.subtract(discount);
    42	        this.status = ReservationStatus.PENDING;
    43	        this.amountPaid = BigDecimal.ZERO;
    44	    }
    45	
    46	    private BigDecimal calculateSubtotal() {
    47	        BigDecimal sum = BigDecimal.ZERO;
    48	        LocalDate date = checkIn;
    49	        while (date.isBefore(checkOut)) {
    50	            BigDecimal nightRate = roomType.getNightlyRate();
    51	            if (isHighSeason(date)) {
    52	                nightRate = nightRate.multiply(new BigDecimal("1.20"))
    53	                    .setScale(2, RoundingMode.HALF_EVEN);
    54	            }
    55	            sum = sum.add(nightRate);
    56	            date = date.plusDays(1);
    57	        }
    58	        return sum.setScale(2, RoundingMode.HALF_EVEN);
    59	    }
    60	
    61	    private boolean isHighSeason(LocalDate date) {
    62	        Month month = date.getMonth();
    63	        int day = date.getDayOfMonth();
    64	
    65	        if (month == Month.DECEMBER && day >= 15) return true;
    66	        if (month == Month.JANUARY || month == Month.FEBRUARY) return true;
    67	        if (month == Month.JULY) return true;
    68	
    69	        return false;
    70	    }
    71	
    72	    private BigDecimal calculateDiscount() {
    73	        BigDecimal discountAmount = subtotal.multiply(ratePlan.getDiscountRate())
    74	            .setScale(2, RoundingMode.HALF_EVEN);
    75	        return discountAmount;
    76	    }
