   210	    private Reservation buildReservation(ResultSet rs) throws SQLException {
   211	        Reservation reservation = new Reservation(
   212	            rs.getString("room_number"),
   213	            RoomType.valueOf(rs.getString("room_type")),
   214	            rs.getString("guest_name"),
   215	            rs.getString("guest_email"),
   216	            rs.getString("guest_cpf"),
   217	            rs.getDate("check_in").toLocalDate(),
   218	            rs.getDate("check_out").toLocalDate(),
   219	            rs.getInt("guests"),
   220	            RatePlan.valueOf(rs.getString("rate_plan"))
   221	        );
   222	
   223	        reservation.setId(rs.getLong("id"));
   224	
   225	        ReservationStatus status = ReservationStatus.valueOf(rs.getString("status"));
   226	        if (status == ReservationStatus.CONFIRMED || status == ReservationStatus.CHECKED_IN || status == ReservationStatus.CHECKED_OUT) {
   227	            reservation.confirm();
