    27	    public Reservation(String roomNumber, RoomType roomType, String guestName, String guestEmail,
    28	                      String guestCpf, LocalDate checkIn, LocalDate checkOut, int guests, RatePlan ratePlan) {
    29	        this.roomNumber = roomNumber;
    30	        this.roomType = roomType;
    31	        this.guestName = guestName;
    32	        this.guestEmail = guestEmail;
    33	        this.guestCpf = guestCpf;
