    45	
    46	    private BigDecimal calculateSubtotal() {
    47	        BigDecimal sum = BigDecimal.ZERO;
    48	        LocalDate date = checkIn;
    49	        while (date.isBefore(checkOut)) {
    50	            BigDecimal nightRate = roomType.getNightlyRate();
    51	            if (isHighSeason(date)) {
    52	                nightRate = nightRate.multiply(new BigDecimal("1.20"))
    53	                    .setScale(2, RoundingMode.HALF_EVEN);
    54	            }
    55	            sum = sum.add(nightRate);
    56	            date = date.plusDays(1);
    57	        }
    58	        return sum.setScale(2, RoundingMode.HALF_EVEN);
    59	    }
    60	
    61	    private boolean isHighSeason(LocalDate date) {
    62	        Month month = date.getMonth();
    63	        int day = date.getDayOfMonth();
    64	
    65	        if (month == Month.DECEMBER && day >= 15) return true;
    66	        if (month == Month.JANUARY || month == Month.FEBRUARY) return true;
    67	        if (month == Month.JULY) return true;
    68	
    69	        return false;
    70	    }
